import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(226,'Fin 2025 : loyers futurs opérating à recevoir 4,280053 Md$, hors baux non commencés ; créances financing leases 8,762238 Md$ brutes mais seulement 502,573 M$ net après intérêts futurs et CECL. Cash reçu financing leases 26,714 M$ distinct du revenu 39,865 M$. Paiements DST master lease de 641,392 M$ sont des sorties, pas des loyers à recevoir ; liés à l’obligation de financement DST, pas à additionner sans contrôle du doublon.','Excludes future minimum rents related to leases with build-to-suit arrangements','lessor_future_rent_excludes_uncommenced_leases',measurement_basis='Dec2025_operating_inflows4_280053bn;financing_receivable502_573m_net;DST_outflows_distinct')
add(227,'En 2025, DST produit net de 299,033 M$ reçu, comptabilisé en obligation de financement de 350,125 M$ : failed sale-leaseback, actifs maintenus au bilan malgré DST non consolidés. Master lease payé même si loyers sous-jacents insuffisants. Rachats ordinaires limités à 5 % NAV par trimestre et suspendables, mais parts du conseiller et performance units disposent de droits spécifiques de remboursement cash. Rachats ordinaires réalisés 331,163 M$, pas nouvelle levée nette.','Net proceeds from DST Interests sold (1)','dst_actual_financing_proceeds_failed_sale_leaseback',stage='drawn_or_paid',candidate_index=13,measurement_basis='FY2025_net_cash299_033m;financing_obligation_not_successful_asset_sale',judgment_sensitive=True)
add(228,'Après décembre et jusqu’à émission des comptes : souscriptions nettes 737,288 M$ et rachats 133,433 M$ sur le même intervalle, à distinguer des flux 2025. Aucune demande non satisfaite déclarée à cette date, sans garantie de liquidité future. Hausse du dividende annuel à 0,75 $ par titre est une déclaration, pas l’intégralité du cash annuel déjà payé.','resulting in net proceeds of $737,288','subsequent_equity_subscription_net_proceeds',stage='drawn_or_paid')
add(229,'Fin 2025 : huit JV datacenter non consolidées, quinze biens, participations de 10,6–65,5 % et valeur de 951,121 M$ ; même plus de 50 % ne prouve pas contrôle. Revenu datacenter sous FV option 248,003 M$ n’est pas cash distribué. Longhorn/Abilene significatif au sens S-X, pas consolidé pour autant. La table regroupe plusieurs projets et ne nomme pas les CTP02/CTP03 ni leurs clients : pas attribution intégrale à CoreWeave.','Net lease data centers (2)','unconsolidated_data_center_jv_carrying_value_scope',candidate_index=32,counterparty_evidence='anonymous',measurement_basis='Dec2025_8JV15properties951_121m_FV;not_all_CoreWeave',judgment_sensitive=True)
add(230,'Management fees payés initialement en titres, mais conseiller a présenté 123,471 M$ de titres au rachat en 2025. Ne pas conclure à l’absence de besoin cash sur ces frais. Performance units également rachetables. Biens acquis auprès de fonds du même conseiller explicitement sans contrôle commun. Prêt affilié remboursé en 2024, pas dette PIK actuelle ; frais STACK de Miner JV plafonnés à 3 % du coût, sans nouvelle identité locataire IA.','for a total of $123,471','adviser_redeemed_fee_shares_cash_requirement',stage='drawn_or_paid',candidate_index=53,counterparty_evidence='anonymous',measurement_basis='FY2025_adviser_fee_share_repurchase123_471m;non_cash_initial_fee_can_require_cash',judgment_sensitive=True)
add(231,'Fin 2025 : immobilier debt FV 1,705886 Md$ exclut CMBS HTM de 384,57 M$ et prêts build-to-suit de 10,691 M$. La moitié du FV est unrated ; maturités indiquées pleinement prolongées, pas premières échéances certaines. Certains actifs gagés et apports futurs demeurent, sans attribution de tout crédit immobilier aux datacenters. Capitalisation d’intérêt et coupon ne prouvent pas une clause PIK dans chaque prêt.','based on the fully extended maturity date of the instrument.','real_estate_credit_fully_extended_maturity_scope',c='context',measurement_basis='Dec2025_FV1_705886bn_excludes_HTM_and_BTS;unrated50percent')
add(232,'Fin 2025 : engagements JV build-to-suit 1,887302 Md$ jusqu’à 2029, incluant datacenters mais sans ventilation CoreWeave. Pour treize autres actifs, coûts payés/accrus 77,917 M$, coût futur estimé 8,921 M$ et plafond contractuel 49,748 M$ non additifs. Prêts futurs 240,984 M$ séparés. Bail Stade HOF garde recours sur le REIT en cas de défaut du sous-locataire, même sans provision matérielle.','estimated future commitments of the Company to complete the construction of the build-to-suit assets is $1,887,302','joint_venture_construction_future_commitment',stage='signed',candidate_index=8,counterparty_evidence='anonymous',measurement_basis='Dec2025_estimate1_887302bn_through2029;not_all_CoreWeave_or_plus_max_BTS',judgment_sensitive=True)
add(233,'Après mars : fusion Sila signée pour un total d’environ 2,5 Md$ avec autres affiliés, engagement equity propre du REIT de 1,2 Md$. Clôture attendue en 2026, pas cash payé ni obligation de 2,5 Md$ entièrement à sa charge. Souscriptions nettes 333,929 M$ sur intervalle post-mars, distinctes du cash au 31 mars et des engagements datacenter.','an equity commitment letter to fund $1,200,000 of equity','subsequent_merger_equity_commitment_not_paid',stage='signed',counterparty='Sila',counterparty_evidence='named',measurement_basis='April2026_issuer_equity1_2bn;totaltransaction2_5bn_not_all_issuer')
add(234,'T1 2026 : management fees 27,907 M$ payés initialement en titres, conseiller présente au rachat 24,741 M$ de titres. Performance allocation 30,457 M$ et unités remboursables accroissent obligations potentielles, sans rachat de ces unités au T1. Frais fondés sur NAV avec intérêts JV en FV peuvent devenir besoin cash ; ne pas additionner charges, titres émis et rachat comme trois coûts.','for repurchase by the Company for a total of $24,741','adviser_fee_share_repurchase_distinct_from_initial_fee',stage='drawn_or_paid',counterparty_evidence='anonymous',measurement_basis='Q1_2026_fee_share_repurchase24_741m;not_plus_FY2025_as_sameperiod')
add(235,'Mars 2026 : engagements JV build-to-suit 1,731652 Md$ jusqu’à 2029, sans ventilation intégrale IA ; ne pas ajouter décembre. Autres coûts estimés 18,174 M$ contre plafond contractuel 47,018 M$ ; améliorations locataire 24,226 M$ et crédit immobilier futur 363,511 M$ distincts. Bail HOF conserve obligation du REIT envers Port Authority si défaut du locataire, malgré paiements directs annoncés.','estimated future commitments of\nthe Company to complete the construction of the build-to-suit assets is $1,731,652','joint_venture_remaining_construction_commitment_stock',stage='signed',counterparty_evidence='anonymous',measurement_basis='March2026_1_731652bn_through2029;not_all_AI_or_plus_Dec_stock')
